using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Automation;using System.Windows.Media;using System.Windows.Threading;using RingTimer;
class IslandLayoutTests {
 static int checks;
 static double Luma(Color c){Func<byte,double> f=v=>{double n=v/255.0;return n<=.04045?n/12.92:Math.Pow((n+.055)/1.055,2.4);};return .2126*f(c.R)+.7152*f(c.G)+.0722*f(c.B);}
 static void CheckCustomContrast(){Theme.Apply(false,"#20352b","#f1f5f2","#9dd9b2");double text=Luma(((SolidColorBrush)Theme.Foreground).Color);foreach(Brush b in new[]{Theme.IslandFill,Theme.IslandHover,Theme.IslandPressed}){double fill=Luma(((SolidColorBrush)b).Color);Check((Math.Max(text,fill)+.05)/(Math.Min(text,fill)+.05)>=4.5,"custom light-mode dark palette keeps readable island text");}Theme.Apply(true,null,null,null);}
 static void CheckSmallDisplay(MenuWindow menu,TimerFeature timer){menu.WorkingHeight=()=>582.4;menu.OpenFeature("timer");menu.Refresh();Pump();Check(menu.MeasurePopup().Height<=582.4,"expanded card fits 125 percent small work area");var scroll=All<ScrollViewer>(menu).First(s=>s.Content is ContentControl);Check(scroll.ScrollableHeight>0,"small display scrolls content instead of cropping controls");scroll.ScrollToBottom();Pump();var start=All<Button>(timer.Panel).Single(b=>AutomationProperties.GetName(b)==L.T("开始工作"));CheckClipping(start,menu);var back=All<Button>(menu).Single(b=>AutomationProperties.GetName(b)==L.T("返回小菜单"));CheckClipping(back,menu);menu.WorkingHeight=null;menu.Refresh();scroll.ScrollToTop();Pump();}
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static IEnumerable<T> All<T>(DependencyObject n) where T:DependencyObject{if(n is T)yield return (T)n;for(int i=0;i<VisualTreeHelper.GetChildrenCount(n);i++)foreach(var x in All<T>(VisualTreeHelper.GetChild(n,i)))yield return x;}
 static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(80)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}
 static void CheckClipping(Button button,MenuWindow menu){DependencyObject node=button;var bounds=button.TransformToAncestor(menu).TransformBounds(new Rect(0,0,button.ActualWidth,button.ActualHeight));while(node!=null&&node!=menu){var visual=node as FrameworkElement;if(visual!=null){var clip=VisualTreeHelper.GetClip(visual);if(clip!=null){var visible=visual.TransformToAncestor(menu).TransformBounds(clip.Bounds);Check(visible.Contains(bounds),"button remains within ancestor clip: "+AutomationProperties.GetName(button)+" "+visual.GetType().Name+" "+visible+" / "+bounds);}}node=VisualTreeHelper.GetParent(node);}}
 static void Capture(MenuWindow menu,string folder,string name){Pump();var surface=menu.CardSurface;Console.WriteLine(name+" surface desired="+surface.DesiredSize+" actual="+surface.ActualHeight+" height="+surface.Height+" valid="+surface.IsMeasureValid+" layer="+surface.Child.DesiredSize);Theme.Snapshot(menu,Path.Combine(folder,name+".png"),1.5);foreach(var b in All<Button>(menu).Where(x=>x.IsVisible&&x.ActualWidth>0)){CheckClipping(b,menu);var p=b.TransformToAncestor(menu).TransformBounds(new Rect(0,0,b.ActualWidth,b.ActualHeight));Check(p.Left>=0&&p.Right<=menu.ActualWidth+1&&p.Top>=0&&p.Bottom<=menu.ActualHeight+1,name+" control inside card: "+AutomationProperties.GetName(b)+" "+p+" / "+menu.ActualWidth+"x"+menu.ActualHeight);}}
 [STAThread]static int Main(string[] args){var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};MenuWindow menu=null;var prefs=new AppearanceSettings(null);try{
 Directory.CreateDirectory(args[0]);CheckCustomContrast();Theme.Apply(true,null,null,null);var now=DateTime.UtcNow;var engine=new TimerEngine(new TimerState(),()=>now);var timer=new TimerFeature(engine,()=>{});var stats=new StatsFeature(new StatsStore(null));var context=new ContextFeature();context.Update(new ContextUsage{ThreadId="layout-demo",Title="当前对话 / Current conversation",Used=70000,Capacity=100000,Known=true});menu=new MenuWindow(new FeatureRegistry(timer,stats,context),()=>{},()=>{},prefs){AnimationsEnabled=false,Left=-2200,Top=0};menu.Reveal();Pump();Check(menu.MeasurePopup().Width==368,"approved card accommodates padded islands");
 CheckSmallDisplay(menu,timer);
 foreach(string lang in new[]{"zh-CN","en"})foreach(bool dark in new[]{true,false}){prefs.Language=lang;Theme.Apply(dark,null,null,null);string prefix=lang+(dark?"-dark-":"-light-");menu.ShowHome();Capture(menu,args[0],prefix+"home");menu.OpenFeature("timer");Capture(menu,args[0],prefix+"timer");double h=menu.MeasurePopup().Height;timer.Panel.OpenEditor("work");Capture(menu,args[0],prefix+"editor");timer.Panel.CancelEditor();menu.OpenFeature("stats");foreach(string view in new[]{"calendar","total","sessions"}){((StatsPanel)stats.View).SelectView(view);Capture(menu,args[0],prefix+view);Check(menu.MeasurePopup().Height==h,"stable timer/statistics height");}menu.OpenFeature("context");Capture(menu,args[0],prefix+"context");menu.OpenSettings();Capture(menu,args[0],prefix+"settings");menu.OpenLanguageSettings();Capture(menu,args[0],prefix+"language");menu.OpenAppearanceSettings();Capture(menu,args[0],prefix+"appearance");menu.OpenSoundSettings();Capture(menu,args[0],prefix+"sound");}
 menu.OpenFeature("timer");timer.Panel.SetDuration(86400);Capture(menu,args[0],"long-duration");timer.Panel.DoPrimary();long deadline=engine.State.Deadline;var control=All<TextBox>(timer.Panel).Single();foreach(int transparency in new[]{0,90,42}){prefs.Transparency=transparency;Theme.Apply(true,"#20352b","#f1f5f2","#9dd9b2");Capture(menu,args[0],"custom-"+transparency);Check(Object.ReferenceEquals(control,All<TextBox>(timer.Panel).Single())&&engine.State.Deadline==deadline,"appearance preserves controls and running deadline");}timer.Panel.DoPrimary();Capture(menu,args[0],"paused");Console.WriteLine(checks+" island layout checks passed");return 0;
 }catch(Exception e){Console.WriteLine("FAIL "+e);return 1;}finally{if(menu!=null){menu.Disposing=true;menu.Close();}prefs.Dispose();app.Shutdown();}}
}
